import Foundation
import XCTest
@testable import ColorComposerCore

/// Wire format of the solver parity corpus generated by the Elixir
/// `color_matching` service (`mix parity.generate`, viamin/color_matching#111).
/// The committed fixture mirrors upstream `priv/parity/v1/corpus.json`
/// byte-for-byte; refresh it only from that source (see
/// `docs/solver-parity-corpus.md`).
struct ParityCorpus: Codable {
    struct PaletteEntry: Codable {
        let index: Int
        let hexColor: String
        let channels: [String: Double]

        enum CodingKeys: String, CodingKey {
            case index
            case hexColor = "hex_color"
            case channels
        }
    }

    struct TargetEntry: Codable {
        let channels: [String: Double]
    }

    /// One expected per-candidate score: either a finite number or the string
    /// `"excluded"` for candidates the missing-measurement policy removes.
    enum ExpectedScore: Equatable {
        case excluded
        case value(Double)
    }

    struct ScoreEntry: Codable {
        let index: Int
        let score: ExpectedScore
    }

    struct Expected: Codable {
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]
        let scores: [ScoreEntry]

        enum CodingKeys: String, CodingKey {
            case selectedIndex = "selected_index"
            case selectedHexColor = "selected_hex_color"
            case error
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
            case scores
        }
    }

    struct Scenario: Codable {
        let id: String
        let description: String
        let palette: [PaletteEntry]
        let target: TargetEntry
        let weights: [String: Double]
        let expected: Expected
    }

    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [Scenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case lightSources = "light_sources"
        case missingPolicy = "missing_policy"
        case scorer
        case selection
        case scenarios
    }
}

extension ParityCorpus.ExpectedScore: Decodable {
    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "parity corpus score must be a number or \"excluded\""
            )
        }
    }
}

/// Replays the committed golden-vector corpus through
/// `WeightedSquaredErrorScorer` and `CompositionSolver` and asserts exact
/// agreement with the Elixir `ColorMatching.WeightedSquaredError` selections —
/// per-candidate scores, tie sets, tie-break winners, exclusions, and weight
/// handling (viamin/color_matching#111, adopted here per issue #39).
final class SolverParityCorpusTests: XCTestCase {
    private static let accuracy = 1e-12

    private static let corpusURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/parity/v1/corpus.json")

    private static let requiredScenarioIDs = [
        "distinct-errors",
        "tie-symmetric-around-target",
        "tie-duplicate-vectors",
        "tie-three-way-on-lps",
        "missing-candidate-excluded",
        "missing-target-excluded",
        "zero-weight-channel-missing",
        "all-excluded",
        "single-channel-lps",
        "exact-match-zero-error",
        "unknown-weight-ignored",
        "mixed-large-palette",
    ]

    // MARK: - Contract metadata

    func testCorpusContractMetadataMatchesTheSupportedVersion() throws {
        let corpus = try Self.loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1, "algorithm_version bump requires corpus refresh + review")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])
    }

    func testCorpusRetainsTieExclusionAndWeightingCoverage() throws {
        let ids = Set(try Self.loadCorpus().scenarios.map(\.id))

        for required in Self.requiredScenarioIDs {
            XCTAssertTrue(ids.contains(required), "corpus lost scenario \(required); regenerate from upstream priv/parity/v1")
        }
    }

    // MARK: - Scorer parity

    func testScenariosScoreSelectAndBreakTiesExactlyLikeTheService() throws {
        let corpus = try Self.loadCorpus()

        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, Self.requiredScenarioIDs.count)
        for scenario in corpus.scenarios {
            replayThroughScorer(scenario)
        }
    }

    private func replayThroughScorer(_ scenario: ParityCorpus.Scenario) {
        let scorer = WeightedSquaredErrorScorer()
        let weights = Self.weights(from: scenario.weights)
        let target = Self.target(from: scenario)
        let palette = Self.domainPalette(for: scenario)

        let outcomes = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }
        XCTAssertEqual(outcomes.count, scenario.expected.scores.count, "scenario \(scenario.id): score table size")

        for (position, expected) in scenario.expected.scores.enumerated() {
            let label = "scenario \(scenario.id) candidate \(expected.index)"
            XCTAssertEqual(expected.index, position, "\(label): palette order")
            switch (outcomes[position], expected.score) {
            case (.excluded, .excluded):
                continue
            case (.score(let value), .value(let expectedValue)):
                XCTAssertEqual(value, expectedValue, accuracy: Self.accuracy, "\(label): score")
            case (.excluded, .value(let expectedValue)):
                XCTFail("\(label): expected score \(expectedValue), received .excluded")
            case (.score(let value), .excluded):
                XCTFail("\(label): expected .excluded, received score \(value)")
            }
        }

        let ranked = outcomes.enumerated().compactMap { pair -> (index: Int, score: Double)? in
            guard case .score(let value) = pair.element else { return nil }
            return (pair.offset, value)
        }
        assertSelection(ranked: ranked, matches: scenario.expected, id: scenario.id, palette: palette)
    }

    /// The corpus records selection as `earliest-index-wins`; this mirrors the
    /// strict less-than policy shared with `IlluminantMatching.best_match/4`.
    private func assertSelection(
        ranked: [(index: Int, score: Double)],
        matches expected: ParityCorpus.Expected,
        id: String,
        palette: [PaletteColor]
    ) {
        let best = ranked.map { $0.score }.min()
        let tied = best.map { bestScore in ranked.filter { abs($0.score - bestScore) <= Self.accuracy }.map { $0.index } }
        let selected = tied?.first

        XCTAssertEqual(selected, expected.selectedIndex, "scenario \(id): selected index")
        XCTAssertEqual(tied ?? [], expected.tiedIndices, "scenario \(id): tied indices")

        if let tieBroke = expected.tieBroke {
            XCTAssertEqual((tied?.count ?? 0) > 1, tieBroke, "scenario \(id): tie_broke evidence")
        }
        if let selected, let expectedHex = expected.selectedHexColor {
            XCTAssertEqual(palette[selected].hex, expectedHex, "scenario \(id): selected hex color")
        }
        if let expectedError = expected.error {
            XCTAssertNotNil(best, "scenario \(id): expected an error but every candidate was excluded")
            if let best {
                XCTAssertEqual(best, expectedError, accuracy: Self.accuracy, "scenario \(id): winning error")
            }
        } else {
            XCTAssertTrue(ranked.isEmpty, "scenario \(id): expected no selection but \(ranked.count) candidates scored")
        }
    }

    // MARK: - Solver parity

    func testSolverSelectsTheCorpusChoices() throws {
        let corpus = try Self.loadCorpus()
        let solver = CompositionSolver()

        for scenario in corpus.scenarios {
            guard scenario.expected.selectedIndex != nil || Self.everyCandidateLacksActiveMeasurements(scenario) else {
                // Target-driven exclusion (e.g. missing-target-excluded) is a
                // scorer-level policy: solver targets are built from grids and
                // always carry every active condition.
                continue
            }
            let result = try solver.solve(
                palette: Self.domainPalette(for: scenario),
                sourceGrids: Self.sourceGrids(for: scenario),
                weights: Self.weights(from: scenario.weights)
            )
            if let selectedIndex = scenario.expected.selectedIndex {
                XCTAssertEqual(result.colorIndices.first ?? nil, selectedIndex, "scenario \(scenario.id): solver selection")
                if let expectedError = scenario.expected.error {
                    XCTAssertEqual(result.errors.first ?? 0, expectedError, accuracy: Self.accuracy, "scenario \(scenario.id): solver error")
                }
            } else {
                XCTAssertNil(result.colorIndices.first ?? nil, "scenario \(scenario.id): expected an unmatched cell")
                XCTAssertEqual(result.unmatchedCellCount, 1, "scenario \(scenario.id): unmatched cells")
                XCTAssertEqual(result.excludedCandidateCount, scenario.palette.count, "scenario \(scenario.id): excluded candidates")
            }
        }
    }

    func testUnknownWeightKeysDoNotActivateChannels() {
        XCTAssertTrue(Self.weights(from: ["ultraviolet": 3.0]).activeConditions.isEmpty)
    }

    // MARK: - Corpus loading and conversion

    private static func loadCorpus() throws -> ParityCorpus {
        do {
            return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: corpusURL))
        } catch {
            XCTFail("parity corpus fixture missing or unreadable at \(corpusURL.path): \(error)")
            throw error
        }
    }

    private static func weights(from dictionary: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: dictionary["white"] ?? 0,
            red: dictionary["red"] ?? 0,
            green: dictionary["green"] ?? 0,
            blue: dictionary["blue"] ?? 0,
            lps: dictionary["lps"] ?? 0
        )
    }

    private static func target(from scenario: ParityCorpus.Scenario) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in scenario.target.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    private static func domainPalette(for scenario: ParityCorpus.Scenario) -> [PaletteColor] {
        scenario.palette.map { entry in
            PaletteColor(
                id: entry.index,
                hex: entry.hexColor,
                rgb: RGBColor(hex: entry.hexColor)!,
                responses: responses(entry.channels)
            )
        }
    }

    private static func responses(_ channels: [String: Double]) -> [LightingCondition: IlluminationResponse] {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, brightness) in channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: brightness)
            }
        }
        return responses
    }

    private static func sourceGrids(for scenario: ParityCorpus.Scenario) -> [LightingCondition: BrightnessGrid] {
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for (condition, _) in weights(from: scenario.weights).activeEntries {
            let value = scenario.target.channels[condition.rawValue] ?? 0
            grids[condition] = BrightnessGrid(width: 1, height: 1, fill: value)
        }
        return grids
    }

    private static func everyCandidateLacksActiveMeasurements(_ scenario: ParityCorpus.Scenario) -> Bool {
        let active = Set(weights(from: scenario.weights).activeConditions)
        return domainPalette(for: scenario).allSatisfy { !$0.hasMeasurements(for: active) }
    }
}
